arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" --data "channel=CJD58H1MBD3&limit=100" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(1)
for m in d['messages']:
    text = m.get('text','')
    if any(k in text.lower() for k in ['payment','gateway','outage']):
        print(m['ts'], '|', m.get('user'), '|', text[:200].replace(chr(10),' '))
"

